// ── Helper ────────────────────────────────────────────────────────────
export function getDayContent(courseId, moduleIndex, dayInModule) {
  const modules = LESSON_CONTENT[courseId]
  if (!modules) return null
  const mod = modules[moduleIndex]
  if (!mod) return null
  return {
    bottomLine:  mod.bottomLine,
    ...(mod.days[dayInModule] || {}),
  }
}
